const CACHE="playlab-offline-v2";
const FILES=["./","./.nojekyll","./app.js","./index.html","./styles.css","./vendor/THIRD_PARTY_LICENSES.txt","./vendor/hooks-compat.js","./vendor/icons.js","./vendor/react-dom.production.min.js","./vendor/react.production.min.js"];
self.addEventListener('install',e=>{e.waitUntil(caches.open(CACHE).then(c=>c.addAll(FILES)).then(()=>self.skipWaiting()))});
self.addEventListener('activate',e=>{e.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k!==CACHE && k.startsWith('playlab-offline')).map(k=>caches.delete(k)))).then(()=>self.clients.claim()))});
self.addEventListener('fetch',e=>{if(e.request.method!=='GET'||new URL(e.request.url).origin!==self.location.origin)return;e.respondWith(caches.match(e.request).then(c=>c||fetch(e.request).then(r=>{if(r.ok){const clone=r.clone();caches.open(CACHE).then(cache=>cache.put(e.request,clone))}return r})))})